<script setup>
import { onMounted, reactive, ref } from 'vue'; import { ElMessage, ElMessageBox } from 'element-plus'; import { api } from '../../lib/api.js'; import { hasPermission } from '../../lib/auth.js'; const rows=ref([]),dialog=ref(false),editing=ref(null); const form=reactive({unitCode:'',unitName:'',precisionScale:0,status:true}); const load=async()=>{try{rows.value=await api.units()}catch(e){ElMessage.error(e.message)}}; function open(x=null){editing.value=x?.id||null;Object.assign(form,x?{unitCode:x.unitCode,unitName:x.unitName,precisionScale:x.precisionScale,status:x.status}:{unitCode:'',unitName:'',precisionScale:0,status:true});dialog.value=true} async function save(){try{editing.value?await api.updateUnit(editing.value,form):await api.createUnit(form);dialog.value=false;await load()}catch(e){ElMessage.error(e.message)}} async function toggle(x){try{await ElMessageBox.confirm('确认切换状态吗？');await api.unitStatus(x.id,!x.status);await load()}catch(e){if(e!=='cancel')ElMessage.error(e.message)}} onMounted(load)
</script><template><div class="page-heading"><h1>单位管理</h1><el-button v-if="hasPermission('system.unit.create')" type="primary" @click="open()">新增单位</el-button></div><el-card><el-table :data="rows"><el-table-column prop="unitCode" label="编号"/><el-table-column prop="unitName" label="名称"/><el-table-column prop="precisionScale" label="精度"/><el-table-column label="状态"><template #default="{row}"><el-tag>{{row.status?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button v-if="hasPermission('system.unit.update')" link @click="open(row)">编辑</el-button><el-button v-if="hasPermission('system.unit.disable')" link @click="toggle(row)">{{row.status?'停用':'启用'}}</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="dialog" :title="editing?'编辑单位':'新增单位'"><el-form label-width="80px"><el-form-item label="编号"><el-input v-model="form.unitCode"/></el-form-item><el-form-item label="名称"><el-input v-model="form.unitName"/></el-form-item><el-form-item label="精度"><el-input-number v-model="form.precisionScale" :min="0" :max="8"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
